import pandas as pd
import numpy as np
from scipy import stats

# Load all experiments
exps = {}
for i in range(1, 6):
    fname = f"experiment_{i}_csv"
    exps[i] = pd.read_csv(eval(fname))
    print(f"\n=== Experiment {i} columns ===")
    print(list(exps[i].columns))
    print(f"Shape: {exps[i].shape}")

    # Check for intervention columns
    for col in exps[i].columns:
        if col.startswith('do_') or col.startswith('add_') or col.startswith('set_'):
            if exps[i][col].notna().any():
                print(f"  Intervention col '{col}': non-NaN count={exps[i][col].notna().sum()}, mean={exps[i][col].mean():.2f}")

# Compare throughput distributions across experiments
print("\n=== Throughput across experiments ===")
for i in range(1, 6):
    print(f"Exp {i}: mean={exps[i]['JobThroughput'].mean():.2f}, std={exps[i]['JobThroughput'].std():.2f}, n={len(exps[i])}")

# Check all correlations with throughput for each experiment
print("\n=== Correlations with JobThroughput ===")
for i in range(1, 6):
    corr = exps[i].corr(numeric_only=True)
    if 'JobThroughput' in corr.columns:
        through_corr = corr['JobThroughput'].drop('JobThroughput').sort_values(key=abs, ascending=False)
        print(f"\nExp {i}:")
        for var, val in through_corr.items():
            print(f"  {var}: {val:.3f}")

import pandas as pd
import os

csv_files = {
    1: "experiment_1_csv",
    2: "experiment_2_csv",
    3: "experiment_3_csv",
    4: "experiment_4_csv",
    5: "experiment_5_csv"
}

# Get actual paths
paths = {k: os.environ.get(v, v) for k, v in csv_files.items()}
# Fallback if env var isn't set, use the literal string if it's a path, otherwise list files
import glob
all_csvs = glob.glob("experiment_*.csv")
if all_csvs:
    paths = {i+1: f for i, f in enumerate(sorted(all_csvs))}

print("Found CSVs:", list(paths.values()))

dfs = {}
for i, path in paths.items():
    try:
        dfs[i] = pd.read_csv(path)
        print(f"\n--- Exp {i} ---")
        print(f"Shape: {dfs[i].shape}")
        print(f"Columns: {list(dfs[i].columns)}")
        print(dfs[i].head(2).to_string())
        print(dfs[i].describe(include='all').T)
    except Exception as e:
        print(f"Error loading Exp {i}: {e}")

# If we got at least one DF, compute correlations across all merged data if possible
if dfs:
    merged = pd.concat(dfs.values(), ignore_index=True)
    numeric_cols = merged.select_dtypes(include='number').columns.tolist()
    if 'JobThroughput' in numeric_cols:
        corr_with_throughput = merged[numeric_cols].corr()['JobThroughput'].drop('JobThroughput').sort_values(ascending=False)
        print("\n=== Correlations with JobThroughput ===")
        print(corr_with_throughput)

